use vstd::prelude::*;

verus! {

fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char>
    requires
        // Every inner vector must be non‐empty so that `.last().unwrap()` is safe
        forall |i: nat| i < l.len() ==> l.index(i).len() > 0,
    ensures
        // The result has the same length as the input list
        result.len() == l.len(),
        // And for each position i, result[i] is the last character of l[i]
        forall |i: nat| i < l.len() ==>
            result.index(i) == l.index(i).index(l.index(i).len() - 1),
{
    let mut r = Vec::with_capacity(l.len());
    for inner in l {
        // safe because of the precondition
        r.push(*inner.last().unwrap());
    }
    r
}

} // end of verus! block

fn main() {
    let input: Vec<Vec<char>> = vec![
        vec!['h', 'e', 'l', 'l', 'o'],
        vec!['w', 'o', 'r', 'l', 'd'],
        vec!['!'],
    ];
    let output = extract_rear_chars(&input);
    assert_eq!(output, vec!['o', 'd', '!']);
    println!("{:?}", output); // prints ['o', 'd', '!']
}